# -*- coding: utf-8 -*-
"""Summarize model characteristics, deficits, training strategies and micro-designs."""
import argparse,json
from pathlib import Path
from architecture_ir import validate_ir,semantic_hash
from orchestrator import atomic_write

def diagnose(model,task,system=None):
 summary=validate_ir(model,task);ops=[n['op'] for n in model['nodes']];params=sum(len(p['value'])*len(p['value'][0]) for p in model['parameters']);family=(system or {}).get('family','custom')
 chars=[{'id':'family','value':family,'basis':'task_observed','confidence':'medium'},{'id':'nodes','value':summary['nodes'],'basis':'ir_derived','confidence':'high'},{'id':'parameters','value':params,'basis':'ir_derived','confidence':'high'},{'id':'operation_proxy','value':summary['scalar_operation_proxy'],'basis':'ir_derived','confidence':'medium'},{'id':'operators','value':ops,'basis':'code_observed','confidence':'high'},{'id':'input_shapes','value':{p['id']:p['shape'] for p in model['inputs']},'basis':'ir_derived','confidence':'high'},{'id':'trainable_parameters','value':[p['id'] for p in model['parameters'] if p.get('trainable')],'basis':'code_observed','confidence':'high'}]
 deficits=[]
 if not any(op in ops for op in ('layernorm','softmax')):deficits.append({'id':'normalization_or_distribution','severity':'medium','observation':'No normalization or distribution-sensitive operator is declared.','risk':'Activation scale or optimization instability may be hidden.','test':'Ablate/add normalization under identical seeds and inspect loss/gradient statistics.'})
 if len(model['nodes'])>4 and not any(n['op']=='add' for n in model['nodes']):deficits.append({'id':'skip_connections','severity':'medium','observation':'Deep graph has no explicit residual add.','risk':'Optimization path may degrade with depth.','test':'Compare residual insertion at matched depth and parameter budget.'})
 if not any(p.get('trainable') for p in model['parameters']):deficits.append({'id':'trainable_state','severity':'high','observation':'No trainable parameter is declared.','risk':'Training claims cannot be executed.','test':'Declare trainable leaves and run gradient/finite-difference checks.'})
 if summary['scalar_operation_proxy']>500000:deficits.append({'id':'compute_budget','severity':'high','observation':'Operation proxy exceeds bounded budget.','risk':'Runtime and memory may be infeasible.','test':'Measure peak memory and latency on target device.'})
 if family in ('transformer','llm') and not any(op=='softmax' for op in ops):deficits.append({'id':'attention_path','severity':'high','observation':'Transformer-family profile lacks explicit softmax path in the supplied IR.','risk':'Attention mechanism is not represented or cannot be audited.','test':'Bind Q/K/V/softmax/O path or mark architecture incomplete.'})
 strategies=[{'id':'baseline_repro','priority':1,'rationale':'Freeze a simple baseline before changing optimization.','changes':['Record seed, split, metric and checkpoint policy.'],'validation_gates':['Baseline completes on development and holdout.'],'failure_conditions':['Missing baseline receipt or target drift.']},{'id':'lr_sweep','priority':2,'rationale':'Test optimization scale before adding architectural complexity.','changes':['Small logarithmic learning-rate sweep','Early stopping on development only'],'validation_gates':['Best setting repeats across declared seeds.'],'failure_conditions':['Unstable loss, NaN, or holdout-only selection.']},{'id':'regularization_ablation','priority':3,'rationale':'Separate capacity gain from overfitting.','changes':['Compare weight decay/dropout/augmentation one factor at a time'],'validation_gates':['Ablation identifies contribution and does not leak holdout.'],'failure_conditions':['Multiple changes confounded or no replay receipt.']}]
 if any(d['id']=='skip_connections' for d in deficits):strategies.append({'id':'residual_warmup','priority':4,'rationale':'Test whether residual paths improve optimization at fixed depth.','changes':['Insert residual branch at the diagnosed block','Warm up branch scale from zero'],'validation_gates':['Matched-budget ablation improves convergence or stability.'],'failure_conditions':['Shape mismatch or improvement disappears on repeated seeds.']})
 micro=[]
 for i,node in enumerate(model['nodes']):
  if node['op'] in ('linear','matmul'):micro.append({'id':'micro:'+node['id']+':norm','target':node['id'],'change':'Add a post-operator normalization candidate with explicit axis and epsilon.','expected_mechanism':'Control activation scale and improve gradient conditioning.','ablation':'Remove normalization while holding seed, data and parameter budget fixed.'})
  if i+2<len(model['nodes']):micro.append({'id':'micro:'+node['id']+':skip','target':node['id'],'change':'Add a typed skip edge to a later compatible node.','expected_mechanism':'Shorten optimization path and preserve low-frequency signal.','ablation':'Compare same-depth graph without skip edge.'})
 return {'schema_version':'1.0','model_hash':semantic_hash(model),'characteristics':chars,'deficits':deficits,'training_strategies':sorted(strategies,key=lambda x:x['priority']),'micro_designs':micro,'evidence_policy':{'observed':'Directly read from task/model/source receipts.','derived':'Computed from validated IR and task contracts.','proposed':'Design hypotheses requiring controlled experiments; never facts.'}}
def main():
 p=argparse.ArgumentParser();p.add_argument('--model',required=True);p.add_argument('--task',required=True);p.add_argument('--system');p.add_argument('-o','--output',required=True);a=p.parse_args()
 try:
  model=json.loads(Path(a.model).read_text(encoding='utf8'));task=json.loads(Path(a.task).read_text(encoding='utf8'));system=json.loads(Path(a.system).read_text(encoding='utf8')) if a.system else None;result=diagnose(model,task,system);atomic_write(a.output,result);print(json.dumps({'status':'completed','deficits':len(result['deficits']),'strategies':len(result['training_strategies']),'micro_designs':len(result['micro_designs'])}))
 except (ValueError,OSError,KeyError) as exc:p.error(str(exc))
if __name__=='__main__':main()
